def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def strip_ns(elem: ET.Element) -> None:
        for e in elem.iter():
            if "}" in e.tag:
                e.tag = e.tag.split("}", 1)[1]

    def parse_xml(xml_text: str) -> dict[str, str]:
        parsed: dict[str, str] = {}
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            # Try removing invalid control chars
            cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", xml_text)
            root = ET.fromstring(cleaned)
        strip_ns(root)

        # If root is <testsuites>, collect all <testsuite>
        testcases = list(root.iter("testcase"))
        for case in testcases:
            name = (case.get("name") or "").strip()
            classname = (case.get("classname") or "").strip()
            if not name and classname:
                name = classname
            if not name:
                continue

            status_attr = (case.get("status") or case.get("result") or "").lower()
            status = "pass"
            if status_attr in {"notrun", "skipped", "skip"}:
                status = "skip"
            elif status_attr in {"fail", "failed", "error"}:
                status = "fail"

            if case.find("failure") is not None or case.find("error") is not None:
                status = "fail"
            elif case.find("skipped") is not None or case.find("skip") is not None:
                status = "skip"

            key = name
            if key in parsed and classname:
                alt_key = f"{classname}.{name}"
                if alt_key not in parsed:
                    key = alt_key
            parsed[key] = status
        return parsed

    # Try XML parsing first
    xml_match = re.search(r"<testsuite\b|<testsuites\b", log)
    if xml_match:
        start = xml_match.start()
        xml_segment = log[start:]
        # Trim to last closing tag to avoid trailing noise
        end = xml_segment.rfind("</testsuites>")
        if end == -1:
            end = xml_segment.rfind("</testsuite>")
            if end != -1:
                end += len("</testsuite>")
        else:
            end += len("</testsuites>")
        if end != -1:
            xml_segment = xml_segment[:end]

        try:
            results = parse_xml(xml_segment)
        except ET.ParseError:
            results = {}

    if results:
        return results

    # Fallback: parse common text formats
    patterns = [
        # pytest
        (re.compile(r"^\s*([^\s:]+::[^\s]+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", re.I), "pytest"),
        # unittest
        (re.compile(r"^\s*([A-Za-z0-9_.]+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", re.I), "unittest"),
        # go test
        (re.compile(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", re.I), "go"),
        # ctest
        (re.compile(r"^Test\s+#\d+:\s+(\S+).*?(Passed|Failed|\*\*\*Failed|SKIPPED)\b", re.I), "ctest"),
        # jest-like
        (re.compile(r"^\s*[✓√]\s+(.+)$"), "jest_pass"),
        (re.compile(r"^\s*[✕×]\s+(.+)$"), "jest_fail"),
        (re.compile(r"^\s*○\s+(.+)$"), "jest_skip"),
    ]

    for line in log.splitlines():
        line = line.rstrip()
        for pattern, kind in patterns:
            m = pattern.search(line)
            if not m:
                continue
            if kind == "pytest":
                name, status_raw = m.group(1), m.group(2).lower()
            elif kind == "unittest":
                name, status_raw = m.group(1), m.group(2).lower()
            elif kind == "go":
                status_raw, name = m.group(1).lower(), m.group(2)
            elif kind == "ctest":
                name, status_raw = m.group(1), m.group(2).lower()
            elif kind == "jest_pass":
                name, status_raw = m.group(1), "pass"
            elif kind == "jest_fail":
                name, status_raw = m.group(1), "fail"
            elif kind == "jest_skip":
                name, status_raw = m.group(1), "skip"
            else:
                continue

            if status_raw in {"passed", "pass", "ok"}:
                status = "pass"
            elif status_raw in {"failed", "fail", "error"}:
                status = "fail"
            elif status_raw in {"skipped", "skip"}:
                status = "skip"
            else:
                status = "pass"
            results[name.strip()] = status
            break

    return results
